"""Validate the payload generated by the frontend export test with the real scaler parser."""
import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(root / 'src'))
from epics_geometry.measurements import parse_measurements

payload = json.loads((root / 'web/.test-output/frontend-measurements.json').read_text())
parsed = parse_measurements(payload)
assert parsed.to_dict() == payload
print('Frontend export accepted unchanged by scaler input validation (all seven measurements).')
